FROM private.authored_event_catalog c WHERE e.case_key=c.case_key AND e.case_key IN ('bank-legal-2026-026','bank-legal-2026-027','bank-legal-2026-028','bank-legal-2026-029','bank-legal-2026-030','bank-legal-2026-031','bank-legal-2026-032','bank-legal-2026-033','bank-legal-2026-034','bank-legal-2026-035','bank-legal-2026-036','bank-legal-2026-037','bank-legal-2026-038','bank-legal-2026-039','bank-legal-2026-040','bank-legal-2026-041','bank-legal-2026-042','bank-legal-2026-043','bank-legal-2026-044','bank-legal-2026-045','bank-legal-2026-046','bank-legal-2026-047','bank-legal-2026-048','bank-legal-2026-049','bank-legal-2026-050')
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=e.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=e.id)
